REPRODUCIBLE VALUE-FREE SOURCE (run from repository root using Node --experimental-transform-types --input-type=module --eval; no file needed). All sensitive-looking test bytes are generated in-process and never printed. This probes a real service-to-decision-store edge using an offline external-output port, not a fabricated receipt:

import { randomBytes } from "node:crypto";
import { SqliteEventStore } from "@moe/store";
import { createDeployService } from "./apps/daemon/src/deployment/deploy-service.js";
import { readDeployReceipt } from "./apps/daemon/src/deployment/deploy-ledger.js";
const projectId = "redaction-flow-probe";
const store = SqliteEventStore.openEphemeralForProjectTest(projectId);
const secret = randomBytes(24).toString("hex");
const detail = "database connection refused postgres://probe:" + secret + "@db.invalid/test";
const unexpected = async () => { throw new Error("UNEXPECTED_PROBE_EFFECT"); };
try {
 const service = createDeployService({ projectId, store, clock: () => "2026-09-08T00:00:00.000Z",
  ports: { docker: async () => ({code: 1, stdout: "", stderr: detail}),
   build: unexpected, ssh: unexpected, transfer: unexpected, releaseDecision: () => null,
   target: () => ({network:"probe-net", sshTarget:null, url:null}) } });
 const report = await service.deploy({context:process.cwd(), decisionId:"probe-decision",
  environment:"staging", sha:"a".repeat(40)});
 const id = report.receipt?.receiptId;
 const read = id ? readDeployReceipt(store, projectId, id) : null;
 console.log(JSON.stringify({ outcome:report.outcome, code:report.receipt?.refusal?.code,
  layer:report.receipt?.refusal?.layer, stored:read?.ok === true,
  rawCredentialReachedDecision:read?.ok === true && Buffer.from(read.decision.resultBytes).includes(Buffer.from(secret)),
  rawCredentialReachedReceipt:read?.ok === true && read.receipt.refusal?.detail.includes(secret) === true }));
} finally { store.close(); }
